  `status` tinyint unsigned DEFAULT NULL COMMENT '状态  0：暂停  1：正常',
  `fail_count` int NOT NULL DEFAULT '0' COMMENT '连续失败次数（成功后清零，达上限自动暂停）',
  `last_error` varchar(2000) DEFAULT NULL COMMENT '最近一次执行失败信息',
  `last_execute_time` datetime DEFAULT NULL COMMENT '上次执行时间',
  `concurrent` tinyint unsigned DEFAULT NULL COMMENT '是否并发  0：禁止  1：允许',
  `remark` varchar(255) DEFAULT NULL COMMENT '备注',
  `version` int DEFAULT NULL COMMENT '版本号',
  `deleted` tinyint DEFAULT NULL COMMENT '删除标识  0：正常   1：已删除',
  `creator` bigint DEFAULT NULL COMMENT '创建者',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `updater` bigint DEFAULT NULL COMMENT '更新者',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=10 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='定时任务';

