  `job_id` bigint NOT NULL COMMENT '任务id',
  `job_name` varchar(200) DEFAULT NULL COMMENT '任务名称',
  `job_group` varchar(100) DEFAULT NULL COMMENT '任务组名',
  `func_name` varchar(200) DEFAULT NULL COMMENT '过程函数名',
  `params` varchar(2000) DEFAULT NULL COMMENT '参数',
  `status` tinyint unsigned NOT NULL COMMENT '任务状态    0：失败    1：成功',
  `error` varchar(2000) DEFAULT NULL COMMENT '异常信息',
  `times` bigint NOT NULL COMMENT '耗时(单位：毫秒)',
  `is_manual` tinyint NOT NULL DEFAULT '0' COMMENT 'trigger type 0 schedule 1 manual',
  `fail_count` int NOT NULL DEFAULT '0' COMMENT '本次失败后的连续失败次数（成功时为0）',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  PRIMARY KEY (`id`),
  KEY `idx_job_id` (`job_id`)
) ENGINE=InnoDB AUTO_INCREMENT=25 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='定时任务日志';

-- ----------------------------
-- Structure for sys_attachment
-- ----------------------------
DROP TABLE IF EXISTS `sys_attachment`;
CREATE TABLE `sys_attachment` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT 'id',
  `name` varchar(255) NOT NULL COMMENT '附件名称',
  `url` varchar(255) NOT NULL COMMENT '附件地址',
  `token` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '随机访问令牌',
  `size_` bigint DEFAULT NULL COMMENT '附件大小',
  `platform` varchar(50) DEFAULT NULL COMMENT '存储平台',
  `tenant_id` bigint DEFAULT NULL COMMENT '租户ID',
  `version` int DEFAULT NULL COMMENT '版本号',
  `deleted` tinyint DEFAULT NULL COMMENT '删除标识  0：正常   1：已删除',
  `creator` bigint DEFAULT NULL COMMENT '创建者',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `updater` bigint DEFAULT NULL COMMENT '更新者',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_token` (`token`)
) ENGINE=InnoDB AUTO_INCREMENT=28 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='附件管理';

-- ----------------------------
-- Structure for sys_basic_config
-- ----------------------------
DROP TABLE IF EXISTS `sys_basic_config`;
CREATE TABLE `sys_basic_config` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT 'id',
  `system_name` varchar(100) DEFAULT NULL COMMENT '系统名称',
  `logo_url` varchar(255) DEFAULT NULL COMMENT '系统Logo地址',
  `captcha_enabled` tinyint DEFAULT NULL COMMENT '登录验证码开关   0：否   1：是',
  `copyright_text` varchar(255) DEFAULT NULL COMMENT '登录页版权文字（支持 {year} 占位符自动取当前年份），空则不显示',
  `icp_code` varchar(100) DEFAULT NULL COMMENT 'ICP备案号，空则不显示',
  `icp_url` varchar(255) DEFAULT NULL COMMENT 'ICP备案链接地址',
  `police_code` varchar(100) DEFAULT NULL COMMENT '公安备案号，空则不显示',
  `version` int DEFAULT NULL COMMENT '版本号',
  `deleted` tinyint DEFAULT NULL COMMENT '删除标识  0：正常   1：已删除',
  `creator` bigint DEFAULT NULL COMMENT '创建者',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `updater` bigint DEFAULT NULL COMMENT '更新者',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='系统维护（全表仅一行记录）';

-- ----------------------------
-- Structure for sys_dict_data
-- ----------------------------
DROP TABLE IF EXISTS `sys_dict_data`;
CREATE TABLE `sys_dict_data` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT 'id',
  `dict_type_id` bigint NOT NULL COMMENT '字典类型ID',
  `dict_label` varchar(255) NOT NULL COMMENT '字典标签',
  `dict_value` varchar(255) DEFAULT NULL COMMENT '字典值',
  `label_class` varchar(100) DEFAULT NULL COMMENT '标签样式',
  `remark` varchar(255) DEFAULT NULL COMMENT '备注',
  `sort` int DEFAULT NULL COMMENT '排序',
  `tenant_id` bigint DEFAULT NULL COMMENT '租户ID',
  `version` int DEFAULT NULL COMMENT '版本号',
  `deleted` tinyint DEFAULT NULL COMMENT '删除标识  0：正常   1：已删除',
  `creator` bigint DEFAULT NULL COMMENT '创建者',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `updater` bigint DEFAULT NULL COMMENT '更新者',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=42 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='字典数据';

-- ----------------------------
-- Structure for sys_dict_type
-- ----------------------------
DROP TABLE IF EXISTS `sys_dict_type`;
CREATE TABLE `sys_dict_type` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT 'id',
  `dict_type` varchar(100) NOT NULL COMMENT '字典类型',
  `dict_name` varchar(255) NOT NULL COMMENT '字典名称',
  `dict_source` tinyint DEFAULT '0' COMMENT '来源  0：字典数据  1：动态SQL',
  `dict_sql` varchar(500) DEFAULT NULL COMMENT '动态SQL',
  `remark` varchar(255) DEFAULT NULL COMMENT '备注',
  `sort` int DEFAULT NULL COMMENT '排序',
  `pid` bigint DEFAULT NULL COMMENT '上级节点',
  `has_child` tinyint DEFAULT '0' COMMENT '是否有子节点',
  `tenant_id` bigint DEFAULT NULL COMMENT '租户ID',
  `version` int DEFAULT NULL COMMENT '版本号',
  `deleted` tinyint DEFAULT NULL COMMENT '删除标识  0：正常   1：已删除',
  `creator` bigint DEFAULT NULL COMMENT '创建者',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `updater` bigint DEFAULT NULL COMMENT '更新者',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=90002 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='字典类型';

-- ----------------------------
-- Structure for sys_ip_address
-- ----------------------------
DROP TABLE IF EXISTS `sys_ip_address`;
CREATE TABLE `sys_ip_address` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT 'id',
  `ip` varchar(64) NOT NULL COMMENT 'IP 地址',
  `address` varchar(255) DEFAULT NULL COMMENT '归属地',
  `source` tinyint DEFAULT '0' COMMENT '来源  1：在线  0：离线降级',
  `resolve_time` datetime DEFAULT NULL COMMENT '解析时间（判缓存有效期用）',
  `version` int DEFAULT NULL COMMENT '版本号',
  `deleted` tinyint DEFAULT NULL COMMENT '删除标识  0：正常   1：已删除',
  `creator` bigint DEFAULT NULL COMMENT '创建者',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `updater` bigint DEFAULT NULL COMMENT '更新者',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_ip` (`ip`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='IP归属地解析缓存（持久化，重启/Redis重建不丢）';

-- ----------------------------
-- Structure for sys_ip_config
-- ----------------------------
DROP TABLE IF EXISTS `sys_ip_config`;
CREATE TABLE `sys_ip_config` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT 'id',
  `enabled` tinyint DEFAULT '0' COMMENT '在线模式开关  0：否（纯离线）  1：是（在线优先，失败降级离线）',
  `query_url` varchar(500) DEFAULT NULL COMMENT '接口地址模板，{ip} 为占位符，如 https://xxx/ip?ip={ip}',
  `request_method` varchar(10) DEFAULT 'GET' COMMENT '请求方式 GET/POST',
  `timeout` int DEFAULT '3000' COMMENT '请求超时（毫秒）',
  `response_type` varchar(10) DEFAULT 'json' COMMENT '返回类型 json/text',
  `field_paths` text COMMENT '字段取值映射 JSON，如 {"pro":"$.province","city":"$.city"}',
  `address_template` varchar(255) DEFAULT NULL COMMENT '地址拼接模板，用 {key} 引用 field_paths 的键，如 {pro}{city}{isp}',
  `cache_days` int DEFAULT '30' COMMENT '归属地缓存有效期（天），0 表示永不过期',
  `version` int DEFAULT NULL COMMENT '版本号',
  `deleted` tinyint DEFAULT NULL COMMENT '删除标识  0：正常   1：已删除',
  `creator` bigint DEFAULT NULL COMMENT '创建者',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `updater` bigint DEFAULT NULL COMMENT '更新者',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='IP归属地在线解析配置（全表仅一行记录）';

-- ----------------------------
-- Structure for sys_log_login
-- ----------------------------
DROP TABLE IF EXISTS `sys_log_login`;
CREATE TABLE `sys_log_login` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT 'id',
  `username` varchar(50) DEFAULT NULL COMMENT '用户名',
  `ip` varchar(32) DEFAULT NULL COMMENT '登录IP',
  `address` varchar(32) DEFAULT NULL COMMENT '登录地点',
  `user_agent` varchar(500) DEFAULT NULL COMMENT 'User Agent',
  `status` tinyint DEFAULT NULL COMMENT '登录状态  0：失败   1：成功',
  `operation` tinyint unsigned DEFAULT NULL COMMENT '操作信息   0：登录成功   1：退出成功  2：验证码错误  3：账号密码错误',
  `tenant_id` bigint DEFAULT NULL COMMENT '租户ID',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='登录日志';

-- ----------------------------
-- Structure for sys_log_operate
-- ----------------------------
DROP TABLE IF EXISTS `sys_log_operate`;
CREATE TABLE `sys_log_operate` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT 'id',
  `module` varchar(100) DEFAULT NULL COMMENT '模块名',
  `name` varchar(100) DEFAULT NULL COMMENT '操作名',
  `req_uri` varchar(200) DEFAULT NULL COMMENT '请求URI',
  `req_method` varchar(20) DEFAULT NULL COMMENT '请求方法',
  `req_params` text COMMENT '请求参数',
  `ip` varchar(32) DEFAULT NULL COMMENT '操作IP',
  `address` varchar(32) DEFAULT NULL COMMENT '登录地点',
  `user_agent` varchar(500) DEFAULT NULL COMMENT 'User Agent',
  `operate_type` tinyint DEFAULT NULL COMMENT '操作类型',
  `duration` int NOT NULL COMMENT '执行时长',
  `status` tinyint DEFAULT NULL COMMENT '操作状态  0：失败   1：成功',
  `user_id` bigint DEFAULT NULL COMMENT '用户ID',
  `real_name` varchar(50) DEFAULT NULL COMMENT '操作人',
  `result_msg` varchar(500) DEFAULT NULL COMMENT '返回消息',
  `tenant_id` bigint DEFAULT NULL COMMENT '租户ID',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='操作日志';

-- ----------------------------
-- Structure for sys_mail_config
-- ----------------------------
DROP TABLE IF EXISTS `sys_mail_config`;
CREATE TABLE `sys_mail_config` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT 'id',
  `platform` tinyint DEFAULT NULL COMMENT '平台类型  -1：本地   0：阿里云',
  `group_name` varchar(100) DEFAULT NULL COMMENT '分组名称，发送邮件时，可指定分组',
  `mail_host` varchar(100) DEFAULT NULL COMMENT 'SMTP服务器',
  `mail_port` int DEFAULT NULL COMMENT 'SMTP端口',
  `mail_from` varchar(100) DEFAULT NULL COMMENT '发件人邮箱',
  `mail_pass` varchar(100) DEFAULT NULL COMMENT '发件人密码',
  `region_id` varchar(100) DEFAULT NULL COMMENT 'regionId',
  `endpoint` varchar(100) DEFAULT NULL COMMENT '阿里云 endpoint',
  `access_key` varchar(100) DEFAULT NULL COMMENT 'AccessKey',
  `secret_key` varchar(100) DEFAULT NULL COMMENT 'SecretKey',
  `status` tinyint DEFAULT NULL COMMENT '状态  0：禁用   1：启用',
  `version` int DEFAULT NULL COMMENT '版本号',
  `deleted` tinyint DEFAULT NULL COMMENT '删除标识  0：正常   1：已删除',
  `creator` bigint DEFAULT NULL COMMENT '创建者',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `updater` bigint DEFAULT NULL COMMENT '更新者',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=6 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='邮件平台';

-- ----------------------------
-- Structure for sys_mail_log
-- ----------------------------
DROP TABLE IF EXISTS `sys_mail_log`;
CREATE TABLE `sys_mail_log` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT 'id',
  `platform_id` bigint DEFAULT NULL COMMENT '平台ID',
  `platform` tinyint DEFAULT NULL COMMENT '平台类型',
  `mail_from` varchar(100) DEFAULT NULL COMMENT '发件人邮箱',
  `mail_tos` varchar(1000) DEFAULT NULL COMMENT '接受人邮箱',
  `subject` varchar(200) DEFAULT NULL COMMENT '邮件主题',
  `content` text COMMENT '邮件内容',
  `status` tinyint DEFAULT NULL COMMENT '状态  0：失败   1：成功',
  `error` varchar(2000) DEFAULT NULL COMMENT '异常信息',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=11 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='邮件日志';

-- ----------------------------
-- Structure for sys_mail_template
-- ----------------------------
DROP TABLE IF EXISTS `sys_mail_template`;
CREATE TABLE `sys_mail_template` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT 'id',
  `template_code` varchar(64) NOT NULL COMMENT '模板编码，发送邮件时按此编码查找模板',
  `template_name` varchar(100) NOT NULL COMMENT '模板名称',
  `subject` varchar(255) DEFAULT NULL COMMENT '邮件主题，支持 ${变量} 占位',
  `content` text COMMENT '邮件正文，支持 ${变量} 占位',
  `mail_format` varchar(10) DEFAULT NULL COMMENT '正文格式  text：纯文本   html：HTML',
  `group_name` varchar(100) DEFAULT NULL COMMENT '发信分组，对应 sys_mail_config.group_name，留空则轮询全部启用分组',
  `status` tinyint DEFAULT NULL COMMENT '状态  0：禁用   1：启用',
  `remark` varchar(500) DEFAULT NULL COMMENT '备注',
  `version` int DEFAULT NULL COMMENT '版本号',
  `deleted` tinyint DEFAULT NULL COMMENT '删除标识  0：正常   1：已删除',
  `creator` bigint DEFAULT NULL COMMENT '创建者',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `updater` bigint DEFAULT NULL COMMENT '更新者',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  PRIMARY KEY (`id`),
  KEY `idx_mail_template_code` (`template_code`)
) ENGINE=InnoDB AUTO_INCREMENT=9 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='邮件模板';

-- ----------------------------
-- Structure for sys_menu
-- ----------------------------
DROP TABLE IF EXISTS `sys_menu`;
CREATE TABLE `sys_menu` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT 'id',
  `pid` bigint DEFAULT NULL COMMENT '上级ID',
  `name` varchar(200) DEFAULT NULL COMMENT '菜单名称',
  `url` varchar(200) DEFAULT NULL COMMENT '菜单URL',
  `authority` varchar(500) DEFAULT NULL COMMENT '授权标识(多个用逗号分隔，如：sys:menu:list,sys:menu:save)',
  `type` tinyint DEFAULT NULL COMMENT '类型   0：菜单   1：按钮   2：接口',
  `open_style` tinyint DEFAULT NULL COMMENT '打开方式   0：内部   1：外部',
  `icon` varchar(50) DEFAULT NULL COMMENT '菜单图标',
  `sort` int DEFAULT NULL COMMENT '排序',
  `version` int DEFAULT NULL COMMENT '版本号',
  `deleted` tinyint DEFAULT NULL COMMENT '删除标识  0：正常   1：已删除',
  `creator` bigint DEFAULT NULL COMMENT '创建者',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `updater` bigint DEFAULT NULL COMMENT '更新者',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  PRIMARY KEY (`id`),
  KEY `idx_menu_pid` (`pid`)
) ENGINE=InnoDB AUTO_INCREMENT=244 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='菜单管理';

-- ----------------------------
-- Structure for sys_message
-- ----------------------------
DROP TABLE IF EXISTS `sys_message`;
CREATE TABLE `sys_message` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT 'id',
  `title` varchar(200) NOT NULL COMMENT '消息标题',
  `content` text COMMENT '消息内容（纯文本，换行原样保留）',
  `send_type` tinyint NOT NULL DEFAULT '1' COMMENT '发送方式  1：全员   2：指定用户',
  `sender_id` bigint DEFAULT NULL COMMENT '发送人ID，匿名发送为空',
  `sender_name` varchar(100) DEFAULT NULL COMMENT '发送人名称',
  `send_source` varchar(20) DEFAULT 'manual' COMMENT '来源  manual：后台发送   template：模板发送   function：过程函数',
  `receiver_count` int DEFAULT '0' COMMENT '接收人数',
  `read_count` int DEFAULT '0' COMMENT '已读人数',
  `remark` varchar(255) DEFAULT NULL COMMENT '备注',
  `version` int DEFAULT NULL COMMENT '版本号',
  `deleted` tinyint DEFAULT NULL COMMENT '删除标识  0：正常   1：已删除',
  `creator` bigint DEFAULT NULL COMMENT '创建者',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `updater` bigint DEFAULT NULL COMMENT '更新者',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  PRIMARY KEY (`id`),
  KEY `idx_create_time` (`create_time`),
  KEY `idx_sender` (`sender_id`)
) ENGINE=InnoDB AUTO_INCREMENT=6 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='站内消息';

-- ----------------------------
-- Structure for sys_message_receiver
-- ----------------------------
DROP TABLE IF EXISTS `sys_message_receiver`;
CREATE TABLE `sys_message_receiver` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT 'id',
  `message_id` bigint NOT NULL COMMENT '消息ID',
  `user_id` bigint NOT NULL COMMENT '接收用户ID',
  `read_status` tinyint NOT NULL DEFAULT '0' COMMENT '阅读状态  0：未读   1：已读',
  `read_time` datetime DEFAULT NULL COMMENT '阅读时间',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_message_user` (`message_id`,`user_id`),
  KEY `idx_user_status` (`user_id`,`read_status`),
  KEY `idx_message` (`message_id`)
) ENGINE=InnoDB AUTO_INCREMENT=6 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='站内消息接收明细';

-- ----------------------------
-- Structure for sys_message_template
-- ----------------------------
DROP TABLE IF EXISTS `sys_message_template`;
CREATE TABLE `sys_message_template` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT 'id',
  `template_code` varchar(100) NOT NULL COMMENT '模板编码，过程函数按此编码取模板',
  `template_name` varchar(100) DEFAULT NULL COMMENT '模板名称',
  `title` varchar(200) DEFAULT NULL COMMENT '消息标题，支持 ${变量} 占位',
  `content` text COMMENT '消息内容，支持 ${变量} 占位',
  `status` tinyint DEFAULT '1' COMMENT '状态  0：禁用   1：启用',
  `remark` varchar(255) DEFAULT NULL COMMENT '备注',
  `version` int DEFAULT NULL COMMENT '版本号',
  `deleted` tinyint DEFAULT NULL COMMENT '删除标识  0：正常   1：已删除',
  `creator` bigint DEFAULT NULL COMMENT '创建者',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `updater` bigint DEFAULT NULL COMMENT '更新者',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  PRIMARY KEY (`id`),
  KEY `idx_template_code` (`template_code`)
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='站内消息模板';

-- ----------------------------
-- Structure for sys_mp_config
-- ----------------------------
DROP TABLE IF EXISTS `sys_mp_config`;
CREATE TABLE `sys_mp_config` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT 'id',
  `config_name` varchar(100) NOT NULL COMMENT '配置名称',
  `env` varchar(10) NOT NULL COMMENT '环境  prod：生产环境  test：测试环境',
  `app_id` varchar(100) NOT NULL COMMENT '公众号 AppID',
  `app_secret` varchar(200) NOT NULL COMMENT '公众号 AppSecret',
  `status` tinyint DEFAULT NULL COMMENT '状态  0：禁用   1：启用',
  `remark` varchar(255) DEFAULT NULL COMMENT '备注',
  `version` int DEFAULT NULL COMMENT '版本号',
  `deleted` tinyint DEFAULT NULL COMMENT '删除标识  0：正常   1：已删除',
  `creator` bigint DEFAULT NULL COMMENT '创建者',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `updater` bigint DEFAULT NULL COMMENT '更新者',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  PRIMARY KEY (`id`),
  KEY `idx_mp_config_env` (`env`)
) ENGINE=InnoDB AUTO_INCREMENT=4 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='微信公众号配置';

-- ----------------------------
-- Structure for sys_mp_log
-- ----------------------------
DROP TABLE IF EXISTS `sys_mp_log`;
CREATE TABLE `sys_mp_log` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT 'id',
  `config_id` bigint DEFAULT NULL COMMENT '配置ID',
  `config_name` varchar(100) DEFAULT NULL COMMENT '配置名称',
  `env` varchar(10) DEFAULT NULL COMMENT '环境  prod：生产  test：测试',
  `app_id` varchar(100) DEFAULT NULL COMMENT '公众号 AppID',
  `template_code` varchar(100) DEFAULT NULL COMMENT '模板编码',
  `msg_type` varchar(20) DEFAULT NULL COMMENT '消息类型  text：文本  card：卡片',
  `to_user` varchar(200) DEFAULT NULL COMMENT '接收人 OpenID',
  `title` varchar(200) DEFAULT NULL COMMENT '卡片标题',
  `content` varchar(2000) DEFAULT NULL COMMENT '消息内容摘要',
  `url` varchar(500) DEFAULT NULL COMMENT '卡片跳转链接',
  `pic_url` varchar(500) DEFAULT NULL COMMENT '卡片封面图 URL',
  `response` varchar(1000) DEFAULT NULL COMMENT '微信原始返回',
  `status` tinyint DEFAULT NULL COMMENT '状态  0：失败   1：成功',
  `error` varchar(2000) DEFAULT NULL COMMENT '异常信息',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  PRIMARY KEY (`id`),
  KEY `idx_mp_log_create_time` (`create_time`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='微信公众号发送日志';

-- ----------------------------
-- Structure for sys_mp_template
-- ----------------------------
DROP TABLE IF EXISTS `sys_mp_template`;
CREATE TABLE `sys_mp_template` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT 'id',
  `template_code` varchar(100) NOT NULL COMMENT '模板编码，发送消息时按此编码查找模板',
  `template_name` varchar(100) NOT NULL COMMENT '模板名称',
  `msg_type` varchar(20) NOT NULL COMMENT '消息类型  text：文本消息  card：卡片消息（图文）',
  `wx_template_id` varchar(100) DEFAULT NULL COMMENT '公众号模板ID：微信模板消息的模板ID，模板消息类型必填',
  `env` varchar(10) NOT NULL COMMENT '使用哪套环境配置  prod：生产环境  test：测试环境',
  `title` varchar(200) DEFAULT NULL COMMENT '卡片标题，支持 ${变量} 占位，文本消息忽略',
  `content` text COMMENT '消息正文 / 卡片描述，支持 ${变量} 占位',
  `url` varchar(500) DEFAULT NULL COMMENT '卡片点击跳转链接，支持 ${变量} 占位',
  `pic_url` varchar(500) DEFAULT NULL COMMENT '卡片封面图 URL，选填',
  `to_user` varchar(1000) DEFAULT NULL COMMENT '默认接收人：公众号 OpenID，多个用逗号或竖线分隔',
  `status` tinyint DEFAULT NULL COMMENT '状态  0：禁用   1：启用',
  `remark` varchar(255) DEFAULT NULL COMMENT '备注',
  `version` int DEFAULT NULL COMMENT '版本号',
  `deleted` tinyint DEFAULT NULL COMMENT '删除标识  0：正常   1：已删除',
  `creator` bigint DEFAULT NULL COMMENT '创建者',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `updater` bigint DEFAULT NULL COMMENT '更新者',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  PRIMARY KEY (`id`),
  KEY `idx_mp_template_code` (`template_code`)
) ENGINE=InnoDB AUTO_INCREMENT=6 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='微信公众号消息模板';

-- ----------------------------
-- Structure for sys_role
-- ----------------------------
DROP TABLE IF EXISTS `sys_role`;
CREATE TABLE `sys_role` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT 'id',
  `name` varchar(50) DEFAULT NULL COMMENT '角色名称',
  `role_code` varchar(50) DEFAULT NULL COMMENT '角色编码',
  `remark` varchar(100) DEFAULT NULL COMMENT '备注',
  `tenant_id` bigint DEFAULT NULL COMMENT '租户ID',
  `version` int DEFAULT NULL COMMENT '版本号',
  `deleted` tinyint DEFAULT NULL COMMENT '删除标识  0：正常   1：已删除',
  `creator` bigint DEFAULT NULL COMMENT '创建者',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `updater` bigint DEFAULT NULL COMMENT '更新者',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='角色管理';

-- ----------------------------
-- Structure for sys_role_menu
-- ----------------------------
DROP TABLE IF EXISTS `sys_role_menu`;
CREATE TABLE `sys_role_menu` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT 'id',
  `role_id` bigint DEFAULT NULL COMMENT '角色ID',
  `menu_id` bigint DEFAULT NULL COMMENT '菜单ID',
  `version` int DEFAULT NULL COMMENT '版本号',
  `deleted` tinyint DEFAULT NULL COMMENT '删除标识  0：正常   1：已删除',
  `creator` bigint DEFAULT NULL COMMENT '创建者',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `updater` bigint DEFAULT NULL COMMENT '更新者',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  PRIMARY KEY (`id`),
  KEY `idx_roleid` (`role_id`),
  KEY `idx_role_menuid` (`menu_id`)
) ENGINE=InnoDB AUTO_INCREMENT=85 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='角色菜单关系';

-- ----------------------------
-- Structure for sys_schema_upgrade
-- ----------------------------
DROP TABLE IF EXISTS `sys_schema_upgrade`;
CREATE TABLE `sys_schema_upgrade` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT 'id',
  `version` varchar(128) COLLATE utf8mb4_general_ci NOT NULL COMMENT '脚本文件名（版本号）',
  `script_name` varchar(255) COLLATE utf8mb4_general_ci NOT NULL COMMENT '脚本资源名',
  `executed_time` datetime NOT NULL COMMENT '执行时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_version` (`version`)
) ENGINE=InnoDB AUTO_INCREMENT=16 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='SQL增量升级执行记录';

-- ----------------------------
-- Structure for sys_storage_config
-- ----------------------------
DROP TABLE IF EXISTS `sys_storage_config`;
CREATE TABLE `sys_storage_config` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT 'id',
  `storage_type` varchar(20) NOT NULL COMMENT '存储类型  LOCAL：本地  WEBDAV：WebDAV',
  `local_path` varchar(255) DEFAULT NULL COMMENT '本地存储根目录',
  `webdav_url` varchar(255) DEFAULT NULL COMMENT 'WebDAV 服务地址',
  `webdav_username` varchar(100) DEFAULT NULL COMMENT 'WebDAV 用户名',
  `webdav_password` varchar(255) DEFAULT NULL COMMENT 'WebDAV 密码',
  `webdav_path` varchar(255) DEFAULT NULL COMMENT 'WebDAV 远程存储目录',
  `domain` varchar(255) DEFAULT NULL COMMENT '对外访问域名',
  `prefix` varchar(255) DEFAULT NULL COMMENT '路径前缀',
  `version` int DEFAULT NULL COMMENT '版本号',
  `deleted` tinyint DEFAULT NULL COMMENT '删除标识  0：正常   1：已删除',
  `creator` bigint DEFAULT NULL COMMENT '创建者',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `updater` bigint DEFAULT NULL COMMENT '更新者',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='文件存储配置（全表仅一行记录）';

-- ----------------------------
-- Structure for sys_trusted_device
-- ----------------------------
DROP TABLE IF EXISTS `sys_trusted_device`;
CREATE TABLE `sys_trusted_device` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT 'id',
  `user_id` bigint NOT NULL COMMENT '用户ID',
  `device_id` varchar(64) NOT NULL COMMENT '设备唯一标识（前端生成的随机UUID）',
  `device_name` varchar(128) DEFAULT NULL COMMENT '设备名称（浏览器/系统拼装）',
  `credential` varchar(64) DEFAULT NULL COMMENT '手机留存凭据的SHA-256摘要',
  `fingerprint` varchar(128) DEFAULT NULL COMMENT '绑定时记录的手机浏览器指纹',
  `user_agent` varchar(512) DEFAULT NULL COMMENT '登录时的 User-Agent',
  `ip` varchar(64) DEFAULT NULL COMMENT '绑定时的IP',
  `status` tinyint DEFAULT '1' COMMENT '状态：1启用 0禁用',
  `bind_time` datetime DEFAULT NULL COMMENT '绑定时间',
  `last_login_time` datetime DEFAULT NULL COMMENT '最近一次免验证码登录时间',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_user_device` (`user_id`,`device_id`),
  UNIQUE KEY `uk_credential` (`credential`)
) ENGINE=InnoDB AUTO_INCREMENT=13 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='信任设备';

-- ----------------------------
-- Structure for sys_user
-- ----------------------------
DROP TABLE IF EXISTS `sys_user`;
CREATE TABLE `sys_user` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT 'id',
  `username` varchar(50) NOT NULL COMMENT '用户名',
  `password` varchar(100) DEFAULT NULL COMMENT '密码',
  `real_name` varchar(50) DEFAULT NULL COMMENT '姓名',
  `avatar` varchar(200) DEFAULT NULL COMMENT '头像',
  `signature` varchar(200) DEFAULT NULL COMMENT '签名',
  `gender` tinyint DEFAULT NULL COMMENT '性别   0：男   1：女   2：未知',
  `email` varchar(100) DEFAULT NULL COMMENT '邮箱',
  `mobile` varchar(20) DEFAULT NULL COMMENT '手机号',
  `super_admin` tinyint DEFAULT NULL COMMENT '超级管理员   0：否   1：是',
  `status` tinyint DEFAULT NULL COMMENT '状态  0：停用   1：正常',
  `tenant_id` bigint DEFAULT NULL COMMENT '租户ID',
  `version` int DEFAULT NULL COMMENT '版本号',
  `deleted` tinyint DEFAULT NULL COMMENT '删除标识  0：正常   1：已删除',
  `creator` bigint DEFAULT NULL COMMENT '创建者',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `updater` bigint DEFAULT NULL COMMENT '更新者',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `pwd_reset_required` tinyint(1) NOT NULL DEFAULT '0' COMMENT '1=首次登录/密码重置后必须修改密码',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=90002 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='用户管理';

-- ----------------------------
-- Structure for sys_user_role
-- ----------------------------
DROP TABLE IF EXISTS `sys_user_role`;
CREATE TABLE `sys_user_role` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT 'id',
  `role_id` bigint DEFAULT NULL COMMENT '角色ID',
  `user_id` bigint DEFAULT NULL COMMENT '用户ID',
  `version` int DEFAULT NULL COMMENT '版本号',
  `deleted` tinyint DEFAULT NULL COMMENT '删除标识  0：正常   1：已删除',
  `creator` bigint DEFAULT NULL COMMENT '创建者',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `updater` bigint DEFAULT NULL COMMENT '更新者',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  PRIMARY KEY (`id`),
  KEY `idx_sys_user_roleid` (`role_id`),
  KEY `idx_sys_user_userid` (`user_id`)
) ENGINE=InnoDB AUTO_INCREMENT=90003 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='用户角色关系';

-- ----------------------------
-- Structure for sys_user_token
-- ----------------------------
DROP TABLE IF EXISTS `sys_user_token`;
CREATE TABLE `sys_user_token` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT 'id',
  `user_id` bigint DEFAULT NULL COMMENT '用户ID',
  `access_token` varchar(32) DEFAULT NULL COMMENT 'accessToken',
  `access_token_expire` datetime DEFAULT NULL COMMENT 'accessToken 过期时间',
  `refresh_token` varchar(32) DEFAULT NULL COMMENT 'refreshToken',
  `refresh_token_expire` datetime DEFAULT NULL COMMENT 'refreshToken 过期时间',
  `tenant_id` bigint DEFAULT NULL COMMENT '租户ID',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='用户Token';

-- ----------------------------
-- Structure for sys_wxwork_config
-- ----------------------------
DROP TABLE IF EXISTS `sys_wxwork_config`;
CREATE TABLE `sys_wxwork_config` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT 'id',
  `config_name` varchar(100) DEFAULT NULL COMMENT '配置名称，发送消息时可指定，留空则轮询启用中的配置',
  `corp_id` varchar(100) DEFAULT NULL COMMENT '企业ID',
  `agent_id` bigint DEFAULT NULL COMMENT '应用AgentId',
  `secret` varchar(200) DEFAULT NULL COMMENT '应用Secret',
  `proxy_url` varchar(200) DEFAULT NULL COMMENT '代理地址，如 http://1.2.3.4:9088；与代理密钥同时填写才走代理模式',
  `proxy_secret` varchar(200) DEFAULT NULL COMMENT '代理密钥，对应代理服务启动参数 --secret',
  `status` tinyint DEFAULT NULL COMMENT '状态  0：禁用   1：启用',
  `remark` varchar(255) DEFAULT NULL COMMENT '备注',
  `version` int DEFAULT NULL COMMENT '版本号',
  `deleted` tinyint DEFAULT NULL COMMENT '删除标识  0：正常   1：已删除',
  `creator` bigint DEFAULT NULL COMMENT '创建者',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `updater` bigint DEFAULT NULL COMMENT '更新者',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='企业微信应用配置';

-- ----------------------------
-- Structure for sys_wxwork_log
-- ----------------------------
DROP TABLE IF EXISTS `sys_wxwork_log`;
CREATE TABLE `sys_wxwork_log` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT 'id',
  `config_id` bigint DEFAULT NULL COMMENT '配置ID',
  `config_name` varchar(100) DEFAULT NULL COMMENT '配置名称',
  `corp_id` varchar(100) DEFAULT NULL COMMENT '企业ID',
  `agent_id` bigint DEFAULT NULL COMMENT '应用AgentId',
  `template_code` varchar(100) DEFAULT NULL COMMENT '模板编码，非模板发送为空',
  `msg_type` varchar(20) DEFAULT NULL COMMENT '消息类型  text：文本   textcard：卡片',
  `to_user` varchar(1000) DEFAULT NULL COMMENT '接收人 UserID，竖线分隔',
  `title` varchar(200) DEFAULT NULL COMMENT '卡片标题',
  `content` varchar(2000) DEFAULT NULL COMMENT '消息内容摘要',
  `url` varchar(500) DEFAULT NULL COMMENT '卡片跳转链接',
  `send_mode` tinyint DEFAULT NULL COMMENT '发送方式  0：直连   1：代理',
  `response` varchar(1000) DEFAULT NULL COMMENT '企业微信原始返回',
  `status` tinyint DEFAULT NULL COMMENT '状态  0：失败   1：成功',
  `error` varchar(2000) DEFAULT NULL COMMENT '异常信息',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  PRIMARY KEY (`id`),
  KEY `idx_create_time` (`create_time`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='企业微信应用发送日志';

-- ----------------------------
-- Structure for sys_wxwork_template
-- ----------------------------
DROP TABLE IF EXISTS `sys_wxwork_template`;
CREATE TABLE `sys_wxwork_template` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT 'id',
  `template_code` varchar(100) DEFAULT NULL COMMENT '模板编码，发送消息时按此编码查找模板',
  `template_name` varchar(100) DEFAULT NULL COMMENT '模板名称',
  `msg_type` varchar(20) DEFAULT NULL COMMENT '消息类型  text：文本消息   textcard：卡片消息',
  `title` varchar(200) DEFAULT NULL COMMENT '卡片标题，支持 ${变量} 占位，文本消息忽略',
  `content` text COMMENT '消息正文 / 卡片描述，支持 ${变量} 占位',
  `url` varchar(500) DEFAULT NULL COMMENT '卡片点击跳转链接，支持 ${变量} 占位',
  `btn_txt` varchar(50) DEFAULT NULL COMMENT '卡片按钮文案，留空默认“详情”',
  `to_user` varchar(1000) DEFAULT NULL COMMENT '默认接收人：企业微信 UserID，多个用竖线或逗号分隔',
  `to_party` varchar(500) DEFAULT NULL COMMENT '接收部门ID，多个用竖线分隔，选填',
  `config_name` varchar(100) DEFAULT NULL COMMENT '配置名称，对应 sys_wxwork_config.config_name，留空则轮询启用中的配置',
  `status` tinyint DEFAULT NULL COMMENT '状态  0：禁用   1：启用',
  `remark` varchar(255) DEFAULT NULL COMMENT '备注',
  `version` int DEFAULT NULL COMMENT '版本号',
  `deleted` tinyint DEFAULT NULL COMMENT '删除标识  0：正常   1：已删除',
  `creator` bigint DEFAULT NULL COMMENT '创建者',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `updater` bigint DEFAULT NULL COMMENT '更新者',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  PRIMARY KEY (`id`),
  KEY `idx_template_code` (`template_code`)
) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='企业微信应用消息模板';

SET FOREIGN_KEY_CHECKS = 1;
